import{_ as l,C as n,o as i,c as s,E as t,a2 as o}from"./chunks/framework.Cm6XCzck.js";const p="/joinwell52/assets/covers/daily-2026-08-19-mobile-decision-boundary-zh.png",f=JSON.parse('{"title":"人离开电脑后，怎样继续掌握 AI 团队？本地运行与手机控制面的双端设计","description":"","frontmatter":{"title":"人离开电脑后，怎样继续掌握 AI 团队？本地运行与手机控制面的双端设计","date":"2026-08-19","column":"digital-employee","category":"daily","article_type":"project-research","edition":"research-center","research_question":"本地 Agent 团队怎样把电脑的权威执行面与手机的受约束控制面分开，同时处理弱网、版本变化、设备吊销与审批边界？","summary":"电脑继续掌握执行和权威事实，手机只提供带版本的观察与决策入口；任何不确定请求都必须回到本地服务重新检查，而不能制造第二个真相。","item_id":"MANUAL-20260819-MOBILE-CONTROL","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-19-local-runtime-mobile-control-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-19-guided-article-pipeline-round1/03-independent-final-package-review-round2.md"]},"headers":[],"relativePath":"zh/digital-employee/2026-08-19-local-runtime-mobile-control.md","filePath":"zh/digital-employee/2026-08-19-local-runtime-mobile-control.md","lastUpdated":1787125010000}'),r={name:"zh/digital-employee/2026-08-19-local-runtime-mobile-control.md"};function c(d,e,h,u,b,g){const a=n("ArticleCover");return i(),s("div",null,[t(a,{image:"/assets/covers/daily-2026-08-19-local-runtime-mobile-control-cover.png",kicker:"数字员工 · 项目研究",title:"人离开电脑后，怎样继续掌握 AI 团队？本地运行与手机控制面的双端设计",summary:"电脑继续掌握执行和权威事实，手机只提供带版本的观察与决策入口；任何不确定请求都必须回到本地服务重新检查，而不能制造第二个真相。",version:"MANUAL-20260819-MOBILE-CONTROL",status:"Independent Editorial PASS · 2026-08-19",languageHref:"/en/digital-employee/2026-08-19-local-runtime-mobile-control",languageLabel:"English"}),e[0]||(e[0]=o(`<h1 id="人离开电脑后-怎样继续掌握-ai-团队-本地运行与手机控制面的双端设计" tabindex="-1">人离开电脑后，怎样继续掌握 AI 团队？本地运行与手机控制面的双端设计 <a class="header-anchor" href="#人离开电脑后-怎样继续掌握-ai-团队-本地运行与手机控制面的双端设计" aria-label="Permalink to &quot;人离开电脑后，怎样继续掌握 AI 团队？本地运行与手机控制面的双端设计&quot;">​</a></h1><p>**系列导航：**先从<a href="/joinwell52/zh/engineering/2026-08-19-taskbook-to-task-graph">长需求施工图</a>理解工作怎样被规划，再用<a href="/joinwell52/zh/engineering/2026-08-19-agent-dispatch-fault-injection">故障注入测试</a>检查运行边界；本篇回答人离开电脑后怎样继续观察和作出受约束决定。</p><h2 id="_10-秒看懂" tabindex="-1">10 秒看懂 <a class="header-anchor" href="#_10-秒看懂" aria-label="Permalink to &quot;10 秒看懂&quot;">​</a></h2><p>电脑继续负责真正干活，手机只负责看进度和做少量关键决定。</p><p>如果手机也保存一套任务状态、也能直接改“已批准”“已完成”，一旦断网、重复点击或任务版本变化，电脑和手机就会各自拥有一个真相。</p><p>稳妥的设计只有一句话：</p><blockquote><p><strong>电脑掌握执行和事实，手机提供受约束的观察与决策入口；手机上的每一次操作，都必须回到电脑端的最新事实重新检查。</strong></p></blockquote><h2 id="地铁里的真实问题-不是-手机能不能打开网页" tabindex="-1">地铁里的真实问题，不是“手机能不能打开网页” <a class="header-anchor" href="#地铁里的真实问题-不是-手机能不能打开网页" aria-label="Permalink to &quot;地铁里的真实问题，不是“手机能不能打开网页”&quot;">​</a></h2><p>晚上七点，一项重构还在家里的电脑上运行。开发 Agent 已提交改动，运维 Agent 正在跑集成测试，测试 Agent 刚发现一个失败。人已经在地铁上。</p><p>此时手机上真正需要的不是一套缩小版开发工具，而是三个答案：</p><ol><li>现在到底进行到哪一步？</li><li>哪一项决定必须由我处理？</li><li>地铁断网后，我的点击会不会被重复执行？</li></ol><p>最危险的做法，是让手机自己维护一份“最新任务库”。电脑上的任务已经进入审核，手机缓存还显示正在执行；手机离线时批准了旧版本，恢复网络后又把这张旧批条补写到已经变化的新任务上。</p><p>这不是页面刷新慢，而是系统出现了两个事实源。</p><h2 id="先划清两层-电脑是执行面-手机是控制面" tabindex="-1">先划清两层：电脑是执行面，手机是控制面 <a class="header-anchor" href="#先划清两层-电脑是执行面-手机是控制面" aria-label="Permalink to &quot;先划清两层：电脑是执行面，手机是控制面&quot;">​</a></h2><p>电脑端负责：</p><ul><li>观察任务文件；</li><li>决定哪些工作满足开工条件；</li><li>启动和管理模型会话；</li><li>运行测试并保存证据；</li><li>记录任务、报告、审查和人的决定。</li></ul><p>手机端负责：</p><ul><li>查看团队和任务状态；</li><li>阅读报告、失败原因和证据摘要；</li><li>处理少量需要人类权限的批准、驳回、暂停或返工；</li><li>查看设备绑定和连接状态。</li></ul><p>手机不能成为第二个运行系统。浏览器里的后台脚本可能被系统随时终止，适合做缓存、离线页面和通知，不适合承担持续数小时的 Agent 执行。<a href="https://www.w3.org/TR/service-workers/" target="_blank" rel="noreferrer">W3C 的 Service Worker 规范</a>也明确把它设计成事件驱动的网络与缓存代理，而不是永远在线的后台进程。</p><p>可以把整个系统想成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>电脑：执行与事实                         手机：受约束控制</span></span>
<span class="line"><span>┌─────────────────────┐                ┌─────────────────────┐</span></span>
<span class="line"><span>│ 启动 Agent 会话      │                │ 查看团队状态         │</span></span>
<span class="line"><span>│ 运行测试             │&lt;──安全连接──&gt;│ 阅读任务与报告       │</span></span>
<span class="line"><span>│ 保存任务与证据       │                │ 提交带版本的决定     │</span></span>
<span class="line"><span>│ 判断恢复或停止       │                │ 查看设备连接         │</span></span>
<span class="line"><span>└──────────┬──────────┘                └──────────┬──────────┘</span></span>
<span class="line"><span>           │ 唯一权威事实                          │ 不保存第二套任务真相</span></span>
<span class="line"><span>           └───────────────────────────────────────┘</span></span></code></pre></div><h2 id="手机最少只需要六类信息" tabindex="-1">手机最少只需要六类信息 <a class="header-anchor" href="#手机最少只需要六类信息" aria-label="Permalink to &quot;手机最少只需要六类信息&quot;">​</a></h2><p>一个好的控制面不靠页面数量取胜。最小集合可以只有：</p><ol><li>**团队状态：**谁空闲、谁忙、谁阻塞、数据是什么时间取得的。</li><li>**任务状态和上下级关系：**当前任务、父任务、子任务、所处阶段和阻塞原因。</li><li>**报告与证据：**谁声称做完了什么，测试通过、失败还是根本没执行，证据在哪里。</li><li>**待处理决定：**哪些对象等待批准、驳回、暂停或返工。</li><li>**关键动态：**只追加的重要事件，而不是把聊天气泡当任务状态。</li><li>**设备状态：**哪些手机已经绑定、最后在线时间、会话是否过期、当前走局域网还是中转服务。</li></ol><p>每个页面都要能回答：“这个数字和状态来自电脑端哪一份权威记录？”</p><p>手机可以保存缓存，但缓存必须明确标成“截至 19:02 的旧视图”，不能冒充实时事实。任务列表、详情、通知和审批页如果各自从不同副本取数，迟早会对同一任务给出不同结论。</p><h2 id="绑定手机-不是一张永久有效的二维码" tabindex="-1">绑定手机，不是一张永久有效的二维码 <a class="header-anchor" href="#绑定手机-不是一张永久有效的二维码" aria-label="Permalink to &quot;绑定手机，不是一张永久有效的二维码&quot;">​</a></h2><p>设备绑定至少要分成两个阶段：短期入口和长期设备身份。</p><p>更严格的目标合同应该是：</p><ol><li>电脑生成一个短期绑定入口，过期自动失效；</li><li>手机首次确认后，待绑定记录只消费一次；</li><li>为应对浏览器重复请求，同一绑定入口可以在很短的窗口内返回第一次的同一结果，但不能创建第二台“幽灵设备”；</li><li>服务器签发可以过期、撤销和轮换的设备会话；</li><li>高风险操作需要重新检查身份和角色，不能只相信手机页面上有一个按钮；</li><li>绑定链接、二维码、会话凭据和真实任务正文不得进入公开截图、代码仓库或普通日志。</li></ol><p>CodeFlowMu 当前实现已经把短期绑定记录、有限时间内的重复请求处理和长期设备身份分开。长期设备记录只保存会话凭据的摘要；为了让同一绑定请求在 10 分钟的重放资格窗口内得到第一次的相同结果，进程内的短期完成记录会暂存原会话凭据。窗口结束后，旧请求不再有资格取回该结果，但记录是在下一次访问该绑定编号时惰性清理，并非由定时器在第 10 分钟准点删除。</p><p>当前代码还提供单设备吊销和“除保留设备外全部吊销”：吊销后设备被禁用，持久记录中的会话摘要与到期时间被移除，后续使用旧凭据的鉴权会失败。PC 管理页也有相应入口。这说明丢失手机后的服务端止损路径已经进入实现，但代码对照不等于完整安全验证；仍需测试已经缓存的页面、正在途中的请求、服务器重启和多端同时操作时，吊销是否始终按预期生效。</p><p>这些取舍必须纳入威胁模型，不能简化成“系统只保存摘要”或“点一下吊销就万事大吉”。真实部署还需要会话轮换、日志脱敏、吊销传播和失窃设备演练。</p><h2 id="手机审批不是改一个-已批准-字段" tabindex="-1">手机审批不是改一个“已批准”字段 <a class="header-anchor" href="#手机审批不是改一个-已批准-字段" aria-label="Permalink to &quot;手机审批不是改一个“已批准”字段&quot;">​</a></h2><p>这是双端系统最容易犯错的地方。</p><h3 id="危险做法" tabindex="-1">危险做法 <a class="header-anchor" href="#危险做法" aria-label="Permalink to &quot;危险做法&quot;">​</a></h3><p>手机只发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务 1：状态改成“已批准”</span></span></code></pre></div><p>地铁进入隧道，请求结果没有返回，手机自动重试三次；与此同时，电脑上的任务已经被另一位管理员修改。服务器如果只看“已批准”三个字，就可能把旧决定重复写入新版本。</p><h3 id="正确做法" tabindex="-1">正确做法 <a class="header-anchor" href="#正确做法" aria-label="Permalink to &quot;正确做法&quot;">​</a></h3><p>下面是一张<strong>目标协议示意</strong>，用于说明一条安全决定至少需要哪些字段；它不是 CodeFlowMu 当前公开 API，也不证明现有手机端已经接入了这项审批。</p><p>手机发送的是一张完整决定单：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>针对对象：任务 1</span></span>
<span class="line"><span>我看到的版本指纹：版本 2.1 / 指纹 123</span></span>
<span class="line"><span>决定：批准进入下一步</span></span>
<span class="line"><span>理由：已检查测试与风险说明</span></span>
<span class="line"><span>防重复流水号：请求 987</span></span></code></pre></div><p>服务器收到后重新读取最新任务：</p><ul><li>版本没变、角色有权、前置条件满足，才追加一次决定；</li><li>版本已经变化，拒绝旧批条，要求重新阅读；</li><li>同一防重复流水号来了三次，只返回第一次结果；</li><li>网络超时，手机显示“结果未知”，不能自己宣布成功；</li><li>批准只代表允许系统尝试下一步，不代表执行已经完成。</li></ul><p>这就是“失败时默认不放行”：只要版本、权限或结果不确定，系统宁可保持只读或等待，也不猜测用户已经批准。</p><h2 id="局域网和中转服务-只改变连接路线" tabindex="-1">局域网和中转服务，只改变连接路线 <a class="header-anchor" href="#局域网和中转服务-只改变连接路线" aria-label="Permalink to &quot;局域网和中转服务，只改变连接路线&quot;">​</a></h2><p>人在同一网络时，手机可以直接连接电脑；离开家或办公室后，可以通过受约束的中转服务转发请求和事件。</p><p>两条路线改变的是“手机怎样找到电脑”，不能改变“谁拥有任务事实和批准权”。无论请求走局域网还是中转服务，最终都必须回到同一个任务读取器、同一个权限检查和同一个决定记录。</p><p>2026 年 8 月 19 日，我们在当前 CodeFlowMu 工作树上重跑了局域网地址选择专项测试，结果为 <strong>5 项执行、5 项通过</strong>。它只证明当前环境中的地址筛选规则，不证明公网穿透、加密传输、中转服务长时间稳定或手机端整体安全。原始命令和输出保存在<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-08-19-guided-article-pipeline-round1/02-experiment-run-log.md" target="_blank" rel="noreferrer">专项实验记录</a>。</p><h2 id="权限漂移-后端、提示和测试必须同时更新" tabindex="-1">权限漂移：后端、提示和测试必须同时更新 <a class="header-anchor" href="#权限漂移-后端、提示和测试必须同时更新" aria-label="Permalink to &quot;权限漂移：后端、提示和测试必须同时更新&quot;">​</a></h2><p>移动控制面演进时，很容易出现一种隐患：后端已经收紧或重新定义权限，手机页面仍展示旧能力，自动化测试也仍按旧规则判断。</p><p>本轮专项检查就发现了一处类似的合同漂移：当前实现仍保持开放版远程发布为只读，但实现使用的权限语义与旧测试期望已经不一致。具体错误码属于开发证据，留在实验记录里；面向读者更重要的是通用教训：</p><blockquote><p><strong>权限边界必须在后端实现、用户提示和自动化测试中三处同时对齐。任何一处落后，手机都可能展示不存在的权限，或把真实限制误报成故障。</strong></p></blockquote><p>测试可以告诉我们“发生了漂移”，却不能代替产品负责人决定新旧规则哪一个具有正式权威。裁决后还必须同步代码、页面文案、错误说明和回归测试。</p><h2 id="弱网与缓存-旧页面可以看-旧决定不能执行" tabindex="-1">弱网与缓存：旧页面可以看，旧决定不能执行 <a class="header-anchor" href="#弱网与缓存-旧页面可以看-旧决定不能执行" aria-label="Permalink to &quot;弱网与缓存：旧页面可以看，旧决定不能执行&quot;">​</a></h2><p>手机可以离线阅读最近一次任务快照，但必须显示数据时间、所见版本和连接状态。</p><p>只显示“截至 19:02”仍然不够。手机系统时间可能因为时区、手工设置或时钟漂移而不准确，缓存是否过期不能只靠客户端墙上时钟判断。更稳妥的界面同时显示两种信息：电脑端生成的观测时间，以及“距离最后一次收到电脑心跳已经过去 X 分钟”。过期与权限判断以服务端时间和服务端规则为准；手机只根据收到心跳后的单调经过时间更新提示，不能用自己的时间把旧快照重新解释成最新状态。</p><p>CodeFlowMu 当前服务已经发送带时间戳的心跳并记录连接的最后活跃时间，但本文没有证据证明所有 PWA 页面都统一实现了上述抗时钟漂移提示。因此，“绝对观测时间 + 心跳间隔 + 服务端过期裁决”应作为下一轮 UI 与弱网测试的明确验收目标，而不是当前完成声明。</p><p>一个实用规则是：</p><ul><li>断网时允许阅读明确标记为“截至某时”的任务和报告；</li><li>离线时不保存可以无条件重放的批准指令；</li><li>恢复连接后先核对版本，再开放写按钮；</li><li>实时通知漏掉后，完整对账仍能找回变化；</li><li>手机版本太旧、数据格式不兼容或权限不确定时，自动进入只读模式。</li></ul><p><a href="https://martin.kleppmann.com/2019/10/23/local-first-at-onward.html" target="_blank" rel="noreferrer">Local-first 软件研究</a>强调本地拥有、离线可用和跨设备协调的价值，但这篇论文不能替我们的实现背书。真实产品仍要测试弱网、时钟偏差、缓存污染、设备撤销和中转服务故障。</p><h2 id="双端验收清单" tabindex="-1">双端验收清单 <a class="header-anchor" href="#双端验收清单" aria-label="Permalink to &quot;双端验收清单&quot;">​</a></h2><p><strong>事实与显示</strong></p><ul><li>手机列表与详情都来自同一任务版本。</li><li>缓存页面同时显示电脑端观测时间和“距最后心跳 X 分钟”，不冒充实时状态。</li><li>缓存过期与写权限由服务端裁决，不依赖手机系统时间是否准确。</li><li>执行报告、审查决定、人的批准和实际完成不会被压成一个“完成”。</li><li>重新联网后的完整对账可以修复漏通知。</li></ul><p><strong>设备与权限</strong></p><ul><li>绑定入口短期有效，待绑定记录只消费一次。</li><li>短窗口内的重复请求只返回同一结果，不创建第二个设备。</li><li>设备会话可过期、撤销和轮换；手机丢失后可从 PC 单独吊销该设备，或只保留最近可信设备。</li><li>吊销后旧凭据的下一次请求必须失败；缓存页面、在途请求和服务器重启后的行为有单独测试。</li><li>高风险动作在服务器重新检查权限，不相信客户端按钮。</li></ul><p><strong>手机写操作</strong></p><ul><li>每个决定都带对象、所见版本、决定、理由和防重复流水号。</li><li>任务版本变化后，旧批条自动失效。</li><li>请求超时显示“结果未知”，不由手机宣布成功。</li><li>人类批准与执行成功分开显示。</li></ul><p><strong>网络与隐私</strong></p><ul><li>局域网和中转路线使用同一事实与权限服务。</li><li>断线、重复请求、服务器重启和设备撤销都有回归测试。</li><li>公开截图、仓库和普通日志不包含二维码、绑定链接、会话凭据或真实任务正文。</li></ul><p>云端运行系统也是有效架构。如果任务本来就在远程沙箱执行，手机可以直接控制云端权威服务。本文讨论的是本地 Agent 团队的故障和信任模型，不主张所有 Agent 都必须在个人电脑上运行。</p><p>对本地系统来说，最好的手机端不是功能最多的手机端，而是人离开电脑后仍能看到同一事实、做少量有权决定，并在网络或版本不确定时拒绝制造第二个真相。</p><h2 id="tmpa、fcop、codeflowmu-和手机端到底是什么关系" tabindex="-1">TMPA、FCoP、CodeFlowMu 和手机端到底是什么关系？ <a class="header-anchor" href="#tmpa、fcop、codeflowmu-和手机端到底是什么关系" aria-label="Permalink to &quot;TMPA、FCoP、CodeFlowMu 和手机端到底是什么关系？&quot;">​</a></h2><p>把四个名称挤在一句话里，读者当然会迷糊。它们不是四个并列产品，而是四个职责不同的层次。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【治理语义】TMPA Core</span></span>
<span class="line"><span>    定义稳定工作载体、角色责任、生命周期状态、独立验收和冲突保留</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>【文件协议】FCoP Profile</span></span>
<span class="line"><span>    将部分治理语义投影为 TASK / REPORT / ISSUE / REVIEW、路径状态与迁移事件</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>【本地工程系统】CodeFlowMu</span></span>
<span class="line"><span>    在当前项目上运行 Agent、测试、依赖、会话、权限、设备绑定与审批服务</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>【远程界面】CodeFlowMu Mobile PWA</span></span>
<span class="line"><span>    显示服务端事实，并把少量受约束的人类请求送回同一个权威服务</span></span></code></pre></div><p>第一层，<a href="https://joinwell52-ai.github.io/joinwell52/zh/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA 核心规范 S1.0</a>是供应商中立的治理语义，不规定电脑、手机或文件系统。它所说的“稳定主载体”是一项工作的稳定引用点，不是“电脑硬盘才是法定主体”。它真正提供的关键边界是：执行报告属于事实声明，有权角色发布的接受决定属于治理裁决，两者不能合并成执行者自己的“已完成”。</p><p>第二层，<a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.md" target="_blank" rel="noreferrer">FCoP</a>把治理协作投影为人机共读的文件。它规定任务、报告、问题、审查、路径状态和迁移事件，但不负责网页怎样到达手机、局域网地址怎样选择、设备凭据怎样签发，也不拥有 Agent 会话。</p><p>第三层，<a href="https://github.com/joinwell52-AI/CodeFlowMu-open" target="_blank" rel="noreferrer">CodeFlowMu Open</a>才是运行中的工程系统。在本文讨论的本地部署里，当前项目根、Runtime 和服务端读取器组成权威执行面；这是 CodeFlowMu 的部署选择，不是 TMPA 对所有系统的要求。CodeFlowMu 还必须区分两类看起来都叫“审批”的动作：任务生命周期里的 REVIEW 属于任务平面；Git 推送、外部写入等高风险操作进入独立的操作审批服务。后者不会因为手机上出现一个 REVIEW 文件就自动获得执行权。</p><p>第四层，手机 PWA 是界面和请求入口。它可以缓存旧视图，却不能成为第二个 Runtime，也不能绕过服务端直接改变权威状态。</p><h2 id="在手机上点一次-批准-真实边界是什么" tabindex="-1">在手机上点一次“批准”，真实边界是什么？ <a class="header-anchor" href="#在手机上点一次-批准-真实边界是什么" aria-label="Permalink to &quot;在手机上点一次“批准”，真实边界是什么？&quot;">​</a></h2><p>一次受控决定可以用五步理解。下面描述的是设计边界，不是把所有决定硬塞进同一种文件或 API。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 手机读取服务端返回的任务、报告、当前版本和连接时间。</span></span>
<span class="line"><span>2. 人点击“批准”，请求携带目标、所见版本、理由和防重复流水号。</span></span>
<span class="line"><span>3. CodeFlowMu 重新检查：设备会话是否仍有效、角色是否有权、目标版本是否变化、请求是否重复。</span></span>
<span class="line"><span>4. 校验通过后：</span></span>
<span class="line"><span>   - 任务复核写入适用的任务/REVIEW 决定链；或</span></span>
<span class="line"><span>   - 高风险操作写入独立的 Operation Approval 记录，只授权那一次精确尝试。</span></span>
<span class="line"><span>5. 后续执行产生新的报告与验证结果；手机稍后读取结果，不能把“已批准”提前显示成“已完成”。</span></span></code></pre></div><p>地铁弱网导致同一请求到达三次时，服务端应返回同一裁决；目标版本变化时，旧请求应被拒绝；设备已经从 PC 吊销时，旧会话不能继续提交决定；请求结果未知时，手机保持“待确认”。至于批准后是否唤醒下游 Agent，要由具体任务依赖或受控执行器决定，不能把每次批准都写成“自动解冻发布任务”。</p><p><img src="`+p+'" alt="目标决定协议中，手机提交带版本和防重复流水号的请求，由本地权威服务检查设备、权限、版本和重放"></p><p><em>图 1：这是目标决定边界，不是当前手机 API 已完整实现的能力声明。手机只作为入口；权威服务应重新检查设备会话、角色能力、目标版本和防重复流水号。FCoP REVIEW 与 Operation Approval 仍属于两个不同平面。来源：TMPA Core S1.0、FCoP v3，以及 CodeFlowMu 当前设备与操作审批实现已经核验的边界。</em></p><p>一句话概括：<strong>TMPA 定义治理语义，FCoP 规定协作工件，CodeFlowMu 承担本地执行与权限裁决，手机只提供受约束的远程入口。</strong></p><h2 id="主要来源" tabindex="-1">主要来源 <a class="header-anchor" href="#主要来源" aria-label="Permalink to &quot;主要来源&quot;">​</a></h2><ul><li><a href="https://joinwell52-ai.github.io/joinwell52/zh/publications/tmpa-architecture-paper-a1.0" target="_blank" rel="noreferrer">TMPA 架构论文 A1.0</a></li><li><a href="https://joinwell52-ai.github.io/joinwell52/zh/publications/tmpa-core-specification-s1.0" target="_blank" rel="noreferrer">TMPA 核心规范 S1.0</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open" target="_blank" rel="noreferrer">CodeFlowMu Open</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/docs/security/operation-approval-boundary.md" target="_blank" rel="noreferrer">CodeFlowMu 操作审批边界</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/mobile/mobileDeviceStore.ts" target="_blank" rel="noreferrer">CodeFlowMu 移动设备存储与吊销</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/mobile/mobileBindStore.ts" target="_blank" rel="noreferrer">CodeFlowMu 移动绑定重放窗口</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/codeflowmu-shell/src/mobile/mobileRoutes.ts" target="_blank" rel="noreferrer">CodeFlowMu 手机路由与心跳</a></li><li><a href="https://www.w3.org/TR/appmanifest/" target="_blank" rel="noreferrer">W3C Web App Manifest</a></li><li><a href="https://www.w3.org/TR/service-workers/" target="_blank" rel="noreferrer">W3C Service Workers</a></li><li><a href="https://martin.kleppmann.com/2019/10/23/local-first-at-onward.html" target="_blank" rel="noreferrer">Local-first software</a></li></ul>',89))])}const w=l(r,[["render",c]]);export{f as __pageData,w as default};
